import{_ as n,y as s,a,o as d,a2 as e,D as o}from"./chunks/framework.DCcmcJcL.js";const f=JSON.parse('{"title":"Orders","description":"","frontmatter":{},"headers":[],"relativePath":"orders/orders.md","filePath":"orders/orders.md","lastUpdated":1789441803000}'),i={name:"orders/orders.md"};function h(g,t,l,c,u,p){const r=s("ImagePopup");return d(),a("div",null,[t[0]||(t[0]=e('<h1 id="orders" tabindex="-1">Orders <a class="header-anchor" href="#orders" aria-label="Permalink to &quot;Orders&quot;">​</a></h1><p>Every sale in your store is an order. The <strong>Orders</strong> screen lists them, and each order has a page where you invoice, ship, refund or cancel it. This page explains that screen, what the order page shows, and how invoices, shipments and refunds move an order from <strong>Pending</strong> to <strong>Completed</strong> or <strong>Closed</strong>.</p><h2 id="how-an-order-works" tabindex="-1">How an order works <a class="header-anchor" href="#how-an-order-works" aria-label="Permalink to &quot;How an order works&quot;">​</a></h2><ol><li>A customer places an order at the storefront checkout, or you <a href="./create-order.html">create one in the admin panel</a>. The order starts as <strong>Pending</strong>.</li><li>You <a href="./create-invoice.html">create an invoice</a> to bill the order. The order moves to <strong>Processing</strong>.</li><li>You <a href="./create-shipment.html">create a shipment</a> to send the products. Products that don&#39;t need shipping, such as virtual and downloadable products, count as shipped once they&#39;re invoiced.</li><li>When everything that wasn&#39;t canceled is invoiced and shipped, the order is <strong>Completed</strong>.</li><li>If the customer gets money back, you <a href="./create-refunds.html">create a refund</a>.</li></ol><p>You can invoice and ship in either order, and do each one in parts.</p><p>Customers can also ask to return items (<a href="./rma.html">RMA</a>) or withdraw from a purchase (<a href="./eu-withdrawal.html">EU Withdrawal</a>). Orders for booking products also appear in <a href="./bookings.html">Bookings</a>.</p><h2 id="the-orders-screen" tabindex="-1">The Orders screen <a class="header-anchor" href="#the-orders-screen" aria-label="Permalink to &quot;The Orders screen&quot;">​</a></h2><p>Go to <strong>Sales &gt;&gt; Orders</strong>.</p>',8)),o(r,{src:"/images/orders/orders-grid.png",alt:"Orders screen listing orders with their status, totals, customer and items"}),t[1]||(t[1]=e('<p>Each row shows:</p><ul><li><strong>Order ID</strong>, <strong>Date</strong> and <strong>Status</strong>: the order number, when the order was placed, and its <a href="#order-statuses">status</a>.</li><li><strong>Grand Total</strong>, <strong>Pay Via</strong> and <strong>Channel</strong>: the order total in the base currency, the payment method (<strong>Pay By - Cash On Delivery</strong>, for example) and the channel it was placed on.</li><li><strong>Customer</strong>, <strong>Email</strong> and <strong>Location</strong>: the customer&#39;s name and email, and the city, state and country of the billing address.</li><li><strong>Items</strong>: pictures of up to three products with their quantities. When the order has more, a tile such as <strong>2 + More Products</strong> is added.</li></ul><p>Click the arrow at the end of a row to open the order.</p><ul><li><strong>Sort</strong>: click <strong>Order ID</strong>, <strong>Date</strong>, <strong>Status</strong>, <strong>Grand Total</strong>, <strong>Customer</strong> or <strong>Email</strong> in the header row.</li><li><strong>Search</strong>: finds orders by order ID, status, customer name or email.</li><li><strong>Filter</strong>: narrows the list by <strong>Order ID</strong>, <strong>Status</strong>, <strong>Grand Total</strong>, <strong>Channel</strong>, <strong>Customer</strong>, <strong>Email</strong> or a <strong>Date</strong> range.</li><li><strong>Export</strong>: downloads the orders as a <strong>CSV</strong>, <strong>XLS</strong> or <strong>XLSX</strong> file. The <strong>Items</strong> column isn&#39;t included.</li><li><strong>Create Order</strong>: starts an order for a customer. See <a href="./create-order.html">Create Order</a>.</li></ul><h2 id="the-order-page" tabindex="-1">The order page <a class="header-anchor" href="#the-order-page" aria-label="Permalink to &quot;The order page&quot;">​</a></h2><p>The title shows the order number, such as <strong>Order #12</strong>, with the order&#39;s status beside it. The buttons below the title are the <a href="#actions-on-an-order">actions</a> the order allows right now.</p>',6)),o(r,{src:"/images/orders/order-view.png",alt:"Order page with the actions, order items, totals and the customer, payment and document cards"}),t[2]||(t[2]=e('<p>If the order contains booking products that customers aren&#39;t allowed to cancel, a <strong>Non-Cancellable Booking Items</strong> notice appears. You can still cancel those items as an admin.</p><h3 id="order-items-and-totals" tabindex="-1">Order items and totals <a class="header-anchor" href="#order-items-and-totals" aria-label="Permalink to &quot;Order items and totals&quot;">​</a></h3><p><strong>Order Items</strong> lists each product with its price per unit and quantity, its options, its <strong>SKU</strong>, and how many units are <strong>Ordered</strong>, <strong>Invoiced</strong>, <strong>Shipped</strong>, <strong>Refunded</strong> and <strong>Canceled</strong>. On the right of each product are its <strong>Price</strong>, <strong>Tax</strong>, <strong>Discount</strong> (when the order has one) and <strong>Sub Total</strong>. Whether prices include tax follows the display settings in <a href="./../configure/taxes.html">Taxes</a>.</p><p>Below the products are the order totals:</p><table tabindex="0"><thead><tr><th>Total</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Sub Total</strong></td><td>The products&#39; total before shipping, tax and discount.</td></tr><tr><td><strong>Shipping and Handling</strong></td><td>The shipping charge. Shown only when the order has products to ship.</td></tr><tr><td><strong>Tax</strong></td><td>The tax on the order.</td></tr><tr><td><strong>Discount</strong></td><td>The discount on the order.</td></tr><tr><td><strong>Grand Total</strong></td><td>What the customer pays for the order.</td></tr><tr><td><strong>Total Paid</strong></td><td>The amount invoiced so far.</td></tr><tr><td><strong>Total Refund</strong></td><td>The amount refunded so far.</td></tr><tr><td><strong>Total Due</strong></td><td>The grand total minus the amount invoiced. A canceled order shows 0.</td></tr></tbody></table><h3 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h3><p>Use <strong>Comments</strong> to keep notes on the order, or to send the customer a message.</p><ol><li>Go to <strong>Sales &gt;&gt; Orders</strong>.</li><li>Open the order.</li><li>In <strong>Comments</strong>, write your comment.</li><li>To email the comment to the customer, tick <strong>Notify Customer</strong>.</li><li>Click <strong>Submit Comment</strong>.</li></ol><p>The comment is listed under the form with its date and <strong>Customer Notified</strong> or <strong>Customer Not Notified</strong>. Comments can&#39;t be edited or deleted.</p><h3 id="customer-payment-and-documents" tabindex="-1">Customer, payment and documents <a class="header-anchor" href="#customer-payment-and-documents" aria-label="Permalink to &quot;Customer, payment and documents&quot;">​</a></h3><p>The cards on the right show:</p><ul><li><strong>Customer</strong>: the customer&#39;s name, email and <strong>Customer Group</strong>, and the <strong>Billing Address</strong> and <strong>Shipping Address</strong>. A guest order shows the guest customer group.</li><li><strong>Order Information</strong>: the <strong>Order Date</strong>, <strong>Order Status</strong> and <strong>Channel</strong>.</li><li><strong>Payment and Shipping</strong>: the payment method, the <strong>Currency</strong> of the order, and any details the payment method adds. For an order with a shipping address, it also shows the <strong>Shipping Method</strong> and <strong>Shipping Price</strong>.</li><li><strong>Invoices</strong>: each invoice with its date, a <strong>View</strong> link and a <strong>Download PDF</strong> link, or <strong>No Invoice Found</strong>.</li><li><strong>Shipments</strong>: each shipment with its date and a <strong>View</strong> link, or <strong>No Shipments Found</strong>.</li><li><strong>Refund</strong>: each refund with its date, the customer&#39;s name, the amount refunded and a <strong>View</strong> link, or <strong>No Refund Found</strong>.</li></ul><p>Payments recorded against the order&#39;s invoices are listed in <a href="./transactions.html">Transactions</a>, not on the order page.</p><h2 id="actions-on-an-order" tabindex="-1">Actions on an order <a class="header-anchor" href="#actions-on-an-order" aria-label="Permalink to &quot;Actions on an order&quot;">​</a></h2><p>Each button appears only when the order allows the action and your role has the permission for it. <strong>Invoice</strong>, <strong>Ship</strong>, <strong>Refund</strong> and <strong>Cancel</strong> aren&#39;t available on a <strong>Closed</strong> or <strong>Fraud</strong> order. <strong>Reorder</strong> can still appear, so you can place the order again.</p><table tabindex="0"><thead><tr><th>Action</th><th>When it appears</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Reorder</strong></td><td>The order belongs to a registered customer, its products can still be sold, and <strong>Admin Reorder</strong> is on in <a href="./../configure/orders-settings.html#allow-reorder">Order Settings</a>.</td><td>Opens <a href="./create-order.html">Create Order</a> for the same customer with the same products in the cart. Booking products are left out, because they need a new date or slot.</td></tr><tr><td><strong>Invoice</strong></td><td>Some quantity isn&#39;t invoiced or canceled yet, and the order wasn&#39;t paid with PayPal Standard.</td><td>Opens <strong>New Invoice</strong>. See <a href="./create-invoice.html">Create Invoice</a>.</td></tr><tr><td><strong>Ship</strong></td><td>Some quantity of a product that needs shipping isn&#39;t shipped, refunded or canceled yet.</td><td>Opens <strong>Create new Shipment</strong>. See <a href="./create-shipment.html">Create Shipment</a>.</td></tr><tr><td><strong>Refund</strong></td><td>Some invoiced quantity or amount isn&#39;t refunded yet.</td><td>Opens <strong>Create Refund</strong>. See <a href="./create-refunds.html">Create Refund</a>.</td></tr><tr><td><strong>Cancel</strong></td><td>Some quantity isn&#39;t invoiced or canceled yet.</td><td>Cancels everything that isn&#39;t invoiced.</td></tr></tbody></table><p>To print or download an invoice, click <strong>Download PDF</strong> in the <strong>Invoices</strong> card, or open the invoice and click <strong>Print</strong>.</p><h3 id="cancel-an-order" tabindex="-1">Cancel an order <a class="header-anchor" href="#cancel-an-order" aria-label="Permalink to &quot;Cancel an order&quot;">​</a></h3><ol><li>Go to <strong>Sales &gt;&gt; Orders</strong>.</li><li>Open the order.</li><li>Click <strong>Cancel</strong>.</li><li>Click <strong>Agree</strong>.</li></ol><p>Only the quantities that aren&#39;t invoiced are canceled. Their stock becomes available for sale again, and links for downloadable products expire. If nothing was invoiced, the order becomes <strong>Canceled</strong>. If part of it was invoiced, the order stays open for that part, and its status is worked out again.</p><p>A cancellation can&#39;t be undone. The customer is emailed if the cancellation email is on in <a href="./../configure/notifications.html">Notifications</a>.</p><p>Customers can also cancel an order from their account on the storefront while part of it isn&#39;t invoiced. Booking products that don&#39;t allow cancellation stay on the order, and an order with only those products can&#39;t be canceled by the customer.</p><h2 id="order-statuses" tabindex="-1">Order statuses <a class="header-anchor" href="#order-statuses" aria-label="Permalink to &quot;Order statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Pending</strong></td><td>The order has been placed and nothing is invoiced, shipped or canceled yet.</td></tr><tr><td><strong>Pending Payment</strong></td><td>The order is waiting for payment. It&#39;s set when you ship an order whose invoice is still <strong>Pending</strong>, or by the payment method&#39;s <strong>Set the order status after creating the invoice to</strong> setting when the invoice is created automatically.</td></tr><tr><td><strong>Processing</strong></td><td>Part of the order is invoiced, shipped, refunded or canceled, but the order isn&#39;t complete.</td></tr><tr><td><strong>Completed</strong></td><td>Everything that wasn&#39;t canceled or refunded is invoiced and shipped. A completed order stays <strong>Completed</strong> after a partial refund.</td></tr><tr><td><strong>Canceled</strong></td><td>Every quantity in the order is canceled.</td></tr><tr><td><strong>Closed</strong></td><td>Every quantity is refunded or canceled, with at least some of it refunded.</td></tr><tr><td><strong>Fraud</strong></td><td>The order has been marked as fraud. No screen in the admin panel sets this status; a payment or fraud-check extension can.</td></tr></tbody></table><h2 id="how-invoices-shipments-and-refunds-change-the-status" tabindex="-1">How invoices, shipments and refunds change the status <a class="header-anchor" href="#how-invoices-shipments-and-refunds-change-the-status" aria-label="Permalink to &quot;How invoices, shipments and refunds change the status&quot;">​</a></h2><p>Bagisto works out the status again each time you invoice, ship, refund or cancel. It counts every unit of every product in the order.</p><table tabindex="0"><thead><tr><th>What happens</th><th>Status afterwards</th></tr></thead><tbody><tr><td>The order is placed.</td><td><strong>Pending</strong></td></tr><tr><td>You invoice part of the order, or all of it with nothing shipped yet.</td><td><strong>Processing</strong></td></tr><tr><td>You invoice all of an order that has no products to ship.</td><td><strong>Completed</strong></td></tr><tr><td>You ship part or all of the order.</td><td><strong>Processing</strong> or <strong>Completed</strong>, or <strong>Pending Payment</strong> if an invoice is still <strong>Pending</strong></td></tr><tr><td>Everything that wasn&#39;t canceled or refunded is invoiced and shipped, and no invoice is <strong>Pending</strong>.</td><td><strong>Completed</strong></td></tr><tr><td>You refund part of the order.</td><td>Usually stays <strong>Processing</strong> or <strong>Completed</strong>. If you refund everything that hasn&#39;t shipped and the rest is shipped, the order becomes <strong>Completed</strong>.</td></tr><tr><td>The payments you record for a <strong>Pending</strong> invoice in <a href="./transactions.html">Transactions</a> reach its total.</td><td><strong>Processing</strong>, or <strong>Completed</strong> once the order has a shipment. Check the order&#39;s status afterwards, especially when only part of it is shipped.</td></tr><tr><td>Everything is refunded, or refunded and canceled.</td><td><strong>Closed</strong></td></tr><tr><td>You cancel an order before anything is invoiced.</td><td><strong>Canceled</strong></td></tr><tr><td>You cancel an order after invoicing part of it.</td><td>The invoiced part carries on: <strong>Processing</strong>, <strong>Completed</strong> or <strong>Closed</strong></td></tr></tbody></table><h3 id="what-can-t-be-undone" tabindex="-1">What can&#39;t be undone <a class="header-anchor" href="#what-can-t-be-undone" aria-label="Permalink to &quot;What can&#39;t be undone&quot;">​</a></h3><ul><li>Invoices, shipments, refunds and cancellations can&#39;t be edited or deleted once they&#39;re created. You can only change an invoice&#39;s status.</li><li>A shipment takes the stock from the inventory source you ship from.</li><li>A cancellation or refund can&#39;t be reversed. To bill the customer again, create a new order.</li></ul><h2 id="emails" tabindex="-1">Emails <a class="header-anchor" href="#emails" aria-label="Permalink to &quot;Emails&quot;">​</a></h2><p>Whether the customer, the admin or the inventory source is emailed when an order is placed, invoiced, shipped, refunded or canceled is set in <a href="./../configure/notifications.html">Notifications</a>.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>A role needs these permissions under <strong>Sales</strong> to work with orders:</p><ul><li><strong>Orders</strong>, with <strong>View</strong>, <strong>Create</strong> and <strong>Cancel</strong>.</li><li><strong>Invoices</strong>, with <strong>View</strong>, <strong>Create</strong> and <strong>Edit</strong>.</li><li><strong>Shipments</strong>, with <strong>View</strong> and <strong>Create</strong>.</li><li><strong>Refunds</strong>, with <strong>View</strong> and <strong>Create</strong>.</li><li><strong>Transactions</strong>, with <strong>View</strong>.</li></ul>',34))])}const w=n(i,[["render",h]]);export{f as __pageData,w as default};
